use rand::Rng;
use std::fmt;

// ============================================================================
// 1. THREE-PLAYER SECURITY DILEMMA — GAME FORM
// ============================================================================

// --- Players ---
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Player { A, B, C }

impl Player {
    /// Each player's primary threat in the cyclical fear structure.
    /// A fears B, B fears C, C fears A.
    fn primary_threat(self) -> Player {
        match self {
            Player::A => Player::B,
            Player::B => Player::C,
            Player::C => Player::A,
        }
    }

    /// Whom this player primarily threatens (inverse of primary_threat).
    fn primary_target(self) -> Player {
        match self {
            Player::A => Player::C,
            Player::B => Player::A,
            Player::C => Player::B,
        }
    }
}

impl fmt::Display for Player {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write"'!(f, "{:?}", self)
    }
}

// --- Private resolve type ---
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Resolve { Low, High }

impl Resolve {
    /// Cost multiplier for arming: high-resolve types bear lower costs.
    fn arm_cost_multiplier(self) -> f64 {
        match self {
            Resolve::Low => 1.5,
            Resolve::High => 0.7,
        }
    }

    /// Benefit from dominance: high-resolve types value it more.
    fn dominance_benefit_multiplier(self) -> f64 {
        match self {
            Resolve::Low => 0.6,
            Resolve::High => 1.4,
        }
    }
}

// --- Actions ---
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Action { Arm, Restrain }

// --- Information set for a player ---
/// What a player knows when choosing an action.
/// Under incomplete information: each player knows their own resolve,
/// receives a noisy signal of others'"' armament, and knows the regime type.
#[derive(Debug, Clone)]
struct InformationSet {
    player: Player,
    own_resolve: Resolve,
    /// Noisy observation of whether the primary threat is arming.
    /// None = no observation (no verification regime).
    threat_arming_signal: Option<bool>,
    /// Noisy observation of the third player's armament.
    third_arming_signal: Option<bool>,
    /// Whether a trilateral verification regime is in place.
    verification_regime: VerificationRegime,
}

// --- Verification regime ---
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VerificationRegime {
    /// No verification; each player sees only noisy public signals.
    None,
    /// Bilateral deal between A and B only; they verify each other but not C.
    BilateralAB,
    /// Trilateral: all three verify all three.
    Trilateral,
}

// --- Payoff structure ---
/// Qualitative payoffs represented as ordinal + cardinal values.
/// The ordinal captures the preference ranking; the cardinal captures
/// the intensity (used for equilibrium selection).
#[derive(Debug, Clone)]
struct Payoff {
    /// Ordinal rank: 0 = worst, 3 = best.
    rank: u8,
    /// Cardinal value (utility).
    value: f64,
    /// Qualitative label.
    label: &'static str,
}

impl fmt::Display for Payoff {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write"'!(f, "{} (rank={}, val={:.2})", self.label, self.rank, self.value)
    }
}

// --- Game state ---
#[derive(Debug, Clone)]
struct GameState {
    /// Private resolve for each player.
    resolve: [Resolve; 3],
    /// Actions chosen.
    actions: [Option<Action>; 3],
    /// Verification regime.
    regime: VerificationRegime,
}

impl GameState {
    fn player_idx(p: Player) -> usize { p as usize }

    fn resolve_of(&self, p: Player) -> Resolve { self.resolve[Self::player_idx(p)] }

    fn action_of(&self, p: Player) -> Option<Action> { self.actions[Self::player_idx(p)] }

    fn set_action(&mut self, p: Player, a: Action) { self.actions[Self::player_idx(p)] = Some(a); }

    /// Compute the payoff for a given player given the full action profile.
    fn payoff_for(&self, p: Player) -> Payoff {
        let threat = p.primary_threat();
        let third = p.primary_target(); // the player whom p threatens
        let own_a = self.action_of(p).unwrap();
        let threat_a = self.action_of(threat).unwrap();
        let third_a = self.action_of(third).unwrap();
        let res = self.resolve_of(p);

        let arm_cost = 2.0 * res.arm_cost_multiplier();
        let dom_benefit = 3.0 * res.dominance_benefit_multiplier();

        match (own_a, threat_a) {
            // Both restrain: cooperative peace.
            (Action::Restrain, Action::Restrain) => {
                // But p still cares about the third player'"'s armament
                // (indirect threat — if third arms, the system is unstable).
                let third_penalty = if third_a == Action::Arm { 0.5 } else { 0.0 };
                let rank = if third_a == Action::Arm { 2 } else { 3 };
                Payoff {
                    rank,
                    value: 2.0 - third_penalty,
                    label: if third_a == Action::Arm {
                        \"cooperative peace (third arms)\"
                    } else {
                        \"cooperative peace (stable)\"
                    },
                }
            }
            // p restrains, threat arms: exploited.
            (Action::Restrain, Action::Arm) => {
                Payoff {
                    rank: 0,
                    value: -dom_benefit,
                    label: \"exploited\",
                }
            }
            // p arms, threat restrains: dominant.
            (Action::Arm, Action::Restrain) => {
                // Cost of arming, but benefit of dominance.
                let third_penalty = if third_a == Action::Arm { 0.5 } else { 0.0 };
                Payoff {
                    rank: 3,
                    value: dom_benefit - arm_cost - third_penalty,
                    label: \"dominant\",
                }
            }
            // Both arm: security dilemma trap.
            (Action::Arm, Action::Arm) => {
                let third_penalty = if third_a == Action::Arm { 1.0 } else { 0.0 };
                Payoff {
                    rank: 1,
                    value: -arm_cost - third_penalty,
                    label: \"arms race trap\",
                }
            }
        }
    }
}

// --- Simulation of a single round ---
struct SimulationResult {
    actions: [Action; 3],
    payoffs: [Payoff; 3],
    regime: VerificationRegime,
    resolves: [Resolve; 3],
}

/// Simulate one round of the game.
/// Each player chooses action based on their information set.
/// The decision rule is a simple best-response heuristic given beliefs.
fn simulate_round(
    resolves: [Resolve; 3],
    regime: VerificationRegime,
    noise: f64, // probability that a signal is flipped
    rng: &mut impl Rng,
) -> SimulationResult {
    let mut state = GameState {
        resolve: resolves,
        actions: [None; 3],
        regime,
    };

    // Players choose simultaneously (order doesn't matter for the
    // information structure — they all choose based on prior beliefs
    // and signals, not on observing others' current choices).
    let players = [Player::A, Player::B, Player::C];

    // Build information sets for each player.
    let info_sets: Vec<InformationSet> = players.iter().map(|&p| {
        let threat = p.primary_threat();
        let third = p.primary_target();

        let threat_arming = resolves[threat as usize] == Resolve::High;
        let third_arming = resolves[third as usize] == Resolve::High;

        let (threat_signal, third_signal) = match regime {
            VerificationRegime::None => {
                // Noisy public signals.
                let ts = if rng.gen::<f64>() < noise {
                    Some("'!threat_arming)
                } else {
                    Some(threat_arming)
                };
                let ths = if rng.gen::<f64>() < noise {
                    Some(!third_arming)
                } else {
                    Some(third_arming)
                };
                (ts, ths)
            }
            VerificationRegime::BilateralAB => {
                // A and B have perfect signals about each other;
                // C has noisy signals about both.
                match p {
                    Player::A => {
                        // A perfectly observes B, noisy on C.
                        (Some(threat_arming), if rng.gen::<f64>() < noise {
                            Some(!third_arming)
                        } else {
                            Some(third_arming)
                        })
                    }
                    Player::B => {
                        // B perfectly observes A (but A is not B'"'s primary threat"'!),
                        // noisy on C (B'"'s primary threat).
                        // This is the key failure: B verifies A but not C.
                        let ts = if rng.gen::<f64>() < noise {
                            Some("'!threat_arming)
                        } else {
                            Some(threat_arming)
                        };
                        (ts, Some(third_arming)) // B perfectly sees A (third).
                    }
                    Player::C => {
                        // C has only noisy signals.
                        let ts = if rng.gen::<f64>() < noise {
                            Some(!threat_arming)
                        } else {
                            Some(threat_arming)
                        };
                        let ths = if rng.gen::<f64>() < noise {
                            Some(!third_arming)
                        } else {
                            Some(third_arming)
                        };
                        (ts, ths)
                    }
                }
            }
            VerificationRegime::Trilateral => {
                // Perfect signals for all players about all others.
                (Some(threat_arming), Some(third_arming))
            }
        };

        InformationSet {
            player: p,
            own_resolve: resolves[p as usize],
            threat_arming_signal: threat_signal,
            third_arming_signal: third_signal,
            verification_regime: regime,
        }
    }).collect();

    // Each player chooses using a threshold rule:
    // Arm if expected benefit of arming > expected benefit of restraining.
    for (i, &p) in players.iter().enumerate() {
        let info = &info_sets[i];
        let res = info.own_resolve;
        let arm_cost = 2.0 * res.arm_cost_multiplier();
        let dom_benefit = 3.0 * res.dominance_benefit_multiplier();

        // Belief that threat is arming (from signal).
        let p_threat_arms = info.threat_arming_signal.map(|s| if s { 1.0 - noise } else { noise })
            .unwrap_or(0.5);

        // Expected utility of arming:
        //   p_threat_arms * (arms race trap payoff) + (1-p_threat_arms) * (dominant payoff)
        let eu_arm = p_threat_arms * (-arm_cost) + (1.0 - p_threat_arms) * (dom_benefit - arm_cost);

        // Expected utility of restraining:
        //   p_threat_arms * (exploited payoff) + (1-p_threat_arms) * (cooperative peace payoff)
        let eu_restrain = p_threat_arms * (-dom_benefit) + (1.0 - p_threat_arms) * 2.0;

        let action = if eu_arm > eu_restrain { Action::Arm } else { Action::Restrain };
        state.set_action(p, action);
    }

    let payoffs = players.map(|p| state.payoff_for(p));

    SimulationResult {
        actions: [state.action_of(Player::A).unwrap(),
                  state.action_of(Player::B).unwrap(),
                  state.action_of(Player::C).unwrap()],
        payoffs,
        regime,
        resolves,
    }
}

// ============================================================================
// 2. TRIANGULATION METHOD — CEASEFIRE ASSESSMENT
// ============================================================================

/// Three observables from open-source proxies.
#[derive(Debug, Clone)]
struct Observables {
    /// Open news: sentiment score from -1.0 (fully hostile) to +1.0 (fully diplomatic).
    news_sentiment: f64,
    /// AIS ship tracking: military logistics vessel activity index (0.0 = peacetime, 1.0 = surge).
    ais_military_logistics: f64,
    /// Electricity/night-lights: military-industrial base activity index.
    /// Composite of rear-area base brightness and industrial power consumption.
    night_lights_military_industrial: f64,
}

/// Hypothesis about the ceasefire.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CeasefireHypothesis {
    /// Genuine de-escalation: parties are disarming and normalizing.
    RealDeescalation,
    /// Pause-to-rearm: parties use the pause to refit, resupply, and prepare.
    PauseToRarm,
}

impl fmt::Display for CeasefireHypothesis {
    fn fmt(&self, f: &mut fmt::Formatter<'"'_>) -> fmt::Result {
        match self {
            CeasefireHypothesis::RealDeescalation => write"'!(f, "Real De-escalation"),
            CeasefireHypothesis::PauseToRarm => write!(f, "Pause-to-Rearm"),
        }
    }
}

