/// Each observable has an expected direction (↑, ↓, →) and the three must
/// be read together because any single observable can be manipulated.
#[derive(Debug)]
struct TriangulationSignature {
    hypothesis: CeasefireHypothesis,
    news_direction: &'"'static str,
    ais_direction: &'static str,
    night_lights_direction: &'static str,
    /// Qualitative description of the co-movement pattern.
    pattern: &'static str,
    /// How the three observables co-move: convergent or divergent.
    convergence: &'static str,
}

fn triangulation_signatures() -> [TriangulationSignature; 2] {
    [
        TriangulationSignature {
            hypothesis: CeasefireHypothesis::RealDeescalation,
            news_direction: \"↑ (diplomatic)\",
            ais_direction: \"↓ (normal)\",
            night_lights_direction: \"↓ (peacetime)\",
            pattern: \"All three converge: news turns diplomatic, military logistics vessels return to peacetime basing patterns, and military-industrial sites dim to normal operating levels. Frontline base electricity drops as alert status lowers.\",
            convergence: \"CONVERGENT — all three proxies move toward normal/peace\",
        },
        TriangulationSignature {
            hypothesis: CeasefireHypothesis::PauseToRarm,
            news_direction: \"↑ (diplomatic — managed)\",
            ais_direction: \"↑ (refit/resupply)\",
            night_lights_direction: \"↑ (rear bases brighten)\",
            pattern: \"Signals diverge: news shows diplomatic framing (hostile rhetoric deliberately suppressed), but AIS tracking reveals military logistics vessels docking at maintenance/refit ports and dual-use cargo imports surging. Night-lights show frontline bases dimming (equipment pulled to rear) while rear-area military-industrial sites brighten (surge production).\",
            convergence: \"DIVERGENT — news says peace, logistics and industry say prepare\",
        },
    ]
}

/// Triangulation method: given three observables, compute a likelihood score
/// for each hypothesis based on co-movement expectations.
///
/// The core logic: under RealDeescalation, all three observables should
/// converge toward normal/peace. Under PauseToRarm, news sentiment may
/// be high (diplomatic) while AIS and night-lights indicate military
/// activity — a divergence pattern.
#[derive(Debug)]
struct TriangulationResult {
    /// Normalized likelihood of real de-escalation [0, 1].
    likelihood_real: f64,
    /// Normalized likelihood of pause-to-rearm [0, 1].
    likelihood_pause: f64,
    /// Which hypothesis is more consistent with the data.
    best_fit: CeasefireHypothesis,
    /// Qualitative interpretation.
    interpretation: &'static str,
}

fn triangulate(obs: &Observables) -> TriangulationResult {
    // Under RealDeescalation:
    //   - news_sentiment should be HIGH (diplomatic) — aligned with peace
    //   - ais_military_logistics should be LOW (peacetime patterns)
    //   - night_lights should be LOW (normal peacetime ops)
    //
    // Under PauseToRarm:
    //   - news_sentiment may be HIGH (deliberately managed rhetoric)
    //   - ais_military_logistics should be HIGH (refit/resupply surge)
    //   - night_lights should be HIGH (rear-area military-industrial surge)
    //
    // The key discriminator: the divergence between news and the other two.
    // If news is high but AIS and night-lights are high, it's PauseToRarm.
    // If all three are low/normal, it's RealDeescalation.

    let divergence_score = obs.ais_military_logistics + obs.night_lights_military_industrial
        - obs.news_sentiment; // high divergence = pause-to-rearm

    // Real de-escalation likelihood: news high, AIS low, night-lights low.
    let real_score = obs.news_sentiment - obs.ais_military_logistics
        - obs.night_lights_military_industrial;

    // Pause-to-rearm likelihood: AIS high, night-lights high
    // (news is irrelevant because it can be managed).
    let pause_score = obs.ais_military_logistics + obs.night_lights_military_industrial;

    // Normalize via softmax-style.
    let exp_real = (real_score.clamp(-5.0, 5.0)).exp();
    let exp_pause = (pause_score.clamp(-5.0, 5.0)).exp();
    let total = exp_real + exp_pause;

    let likelihood_real = exp_real / total;
    let likelihood_pause = exp_pause / total;

    let best_fit = if likelihood_pause > likelihood_real {
        CeasefireHypothesis::PauseToRarm
    } else {
        CeasefireHypothesis::RealDeescalation
    };

    let interpretation = if divergence_score > 0.5 {
        \"DIVERGENT: news says peace but logistics and industrial activity suggest preparation. Consistent with pause-to-rearm.\"
    } else if divergence_score < -0.5 {
        \"CONVERGENT: news, logistics, and industrial activity all align toward normalcy. Consistent with real de-escalation.\"
    } else {
        \"AMBIGUOUS: signals are mixed; more observation time needed.\"
    };

    TriangulationResult {
        likelihood_real,
        likelihood_pause,
        best_fit,
        interpretation,
    }
}

/// Generate a set of observables for a given hypothesis (for demonstration).
fn generate_observables(hypothesis: CeasefireHypothesis, rng: &mut impl Rng) -> Observables {
    let noise = |mean: f64, std: f64| -> f64 {
        let u: f64 = rng.gen();
        let v: f64 = rng.gen();
        let z = (-2.0 * u.ln()).sqrt() * (2.0 * std::f64::consts::PI * v).cos();
        (mean + std * z).clamp(-1.0, 1.0)
    };

    match hypothesis {
        CeasefireHypothesis::RealDeescalation => Observables {
            news_sentiment: noise(0.6, 0.15),
            ais_military_logistics: noise(0.2, 0.1),
            night_lights_military_industrial: noise(0.15, 0.1),
        },
        CeasefireHypothesis::PauseToRarm => Observables {
            news_sentiment: noise(0.5, 0.2),   // managed diplomatic tone
            ais_military_logistics: noise(0.7, 0.15),  // refit/resupply surge
            night_lights_military_industrial: noise(0.65, 0.15),  // rear bases active
        },
    }
}

